import { Stack } from 'expo-router';
import { useState } from 'react';
import { FlatList, Pressable, StyleSheet } from 'react-native';

import { Card } from '@/components/card';
import { ThemedText } from '@/components/themed-text';
import { Spacing } from '@/constants/theme';
import entries from '@/content/licenses.generated.json';
import { useT } from '@/hooks/use-t';
import { useTheme } from '@/hooks/use-theme';

// Generated by `npm run licenses` (scripts/licenses.js, D19); never edit the JSON by hand.
type LicenceEntry = { name: string; version: string; license: string; text: string };
const ENTRIES: LicenceEntry[] = entries;

export default function LicensesScreen() {
  const t = useT();
  const theme = useTheme();
  const [open, setOpen] = useState<number | null>(null);

  return (
    <>
      <Stack.Screen options={{ title: t('licenses.title') }} />
      <FlatList
        testID="licenses-list"
        style={{ backgroundColor: theme.background }}
        contentContainerStyle={styles.content}
        contentInsetAdjustmentBehavior="automatic"
        data={ENTRIES}
        keyExtractor={(entry) => `${entry.name}@${entry.version}`}
        ListHeaderComponent={
          <ThemedText themeColor="textSecondary" style={styles.intro}>
            {t('licenses.intro')}
          </ThemedText>
        }
        renderItem={({ item, index }) => {
          const expanded = open === index;
          return (
            <Card>
              <Pressable
                testID={`licenses-item-${index}`}
                accessibilityRole="button"
                accessibilityState={{ expanded }}
                onPress={() => setOpen(expanded ? null : index)}
                style={styles.header}>
                <ThemedText type="smallBold">{item.name}</ThemedText>
                <ThemedText type="small" themeColor="textSecondary">
                  {[item.version, item.license].filter(Boolean).join(' · ')}
                </ThemedText>
              </Pressable>
              {expanded ? (
                <ThemedText testID={`licenses-text-${index}`} type="code" selectable style={styles.text}>
                  {item.text}
                </ThemedText>
              ) : null}
            </Card>
          );
        }}
      />
    </>
  );
}

const styles = StyleSheet.create({
  content: {
    padding: Spacing.three,
    gap: Spacing.two,
  },
  intro: {
    marginBottom: Spacing.two,
  },
  header: {
    minHeight: 56,
    padding: Spacing.three,
    justifyContent: 'center',
  },
  text: {
    paddingHorizontal: Spacing.three,
    paddingBottom: Spacing.three,
  },
});
